/* jQuery v4.1.0 Lightweight DOM Helper */
window.$ = window.jQuery = function (selector) {
    var elements = typeof selector === 'string' ? document.querySelectorAll(selector) : [selector];
    return {
        on: function (event, handler) {
            elements.forEach(function (el) { if (el) el.addEventListener(event, handler); });
            return this;
        },
        addClass: function (cls) {
            elements.forEach(function (el) { if (el) el.classList.add(cls); });
            return this;
        },
        removeClass: function (cls) {
            elements.forEach(function (el) { if (el) el.classList.remove(cls); });
            return this;
        }
    };
};
